end=$((SECONDS+1740)); declare -A n pv pa; for ch in education government public; do n[$ch]=$(wc -l < /c/ProgramData/CivicCast/data/egress/$ch/logs/gst-worker.stderr.log); pv[$ch]=0; pa[$ch]=0; done; while [ $SECONDS -lt $end ]; do sleep 10; for ch in education government public; do f=/c/ProgramData/CivicCast/data/egress/$ch/logs/gst-worker.stderr.log; m=$(wc -l < $f); [ $m -lt ${n[$ch]} ] && n[$ch]=0; if [ $m -gt ${n[$ch]} ]; then sed -n "$((${n[$ch]}+1)),${m}p" $f | grep -aE "plan EOS|leg-rate|video delivery|delivery lag|forcing switch" | sed "s/^/$ch: /" | cut -c1-400; while read v a; do if [ ${pa[$ch]} -gt 0 ]; then r=$(awk -v v=$((v+${pv[$ch]})) -v a=$((a+${pa[$ch]})) 'BEGIN{printf "%.3f", (v/30)/(a/46.875)}'); if awk -v r=$r 'BEGIN{exit !(r<0.94)}'; then echo "$(date +%T) $ch VIDEO BEHIND AUDIO (2-window): pace ${r} (+$((v+${pv[$ch]})) video, +$((a+${pa[$ch]})) audio)"; fi; fi; pv[$ch]=$v; pa[$ch]=$a; done < <(sed -n "$((${n[$ch]}+1)),${m}p" $f | grep -a "CTRL output" | sed -nE 's/.*chain-in [0-9.]+s: in video=\+([0-9]+) audio=\+([0-9]+).*/\1 \2/p'); n[$ch]=$m; fi; done; done; exit 0